begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(19);
create temporary table results(result text);
create temporary table ctx(bid uuid,cid uuid,sid uuid,eid uuid);
grant all on results,ctx to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000021',true);
update ctx set cid=(public.expense_command('category_create',jsonb_build_object('business_id',bid,'name','Rent')) #>> '{}')::uuid;
select public.expense_command('create',jsonb_build_object('business_id',bid,'category_id',cid,'request_id',sid,'title','Rent','description','','amount','100.25','due_date','2026-01-31','frequency','monthly','end_date','2026-03-31')) from ctx;
select public.expense_command('create',jsonb_build_object('business_id',bid,'category_id',cid,'request_id',sid,'title','Rent','amount','100.25','due_date','2026-01-31','frequency','monthly','end_date','2026-03-31')) from ctx;
update ctx set eid=(select id from public.expenses where business_id=ctx.bid order by due_date limit 1);
select public.expense_command('delete',jsonb_build_object('business_id',bid,'id',eid,'version',1)) from ctx;
select public.expense_command('restore',jsonb_build_object('business_id',bid,'id',eid,'version',2)) from ctx;
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000022',true);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000023',true);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000021',true);
select public.expense_command('update',jsonb_build_object('business_id',bid,'id',eid,'version',3,'category_id',cid,'title','Adjusted rent','description','Correction','amount','90.10','due_date','2026-02-01')) from ctx;
select public.flowledger_command('archive_business',jsonb_build_object('business_id',bid,'archived',true)) from ctx;
select result from results;
rollback;
