insert into auth.users(id,email,email_confirmed_at) values
 ('00000000-0000-0000-0000-000000000021','expense-owner@test.invalid',now()),
 ('00000000-0000-0000-0000-000000000022','expense-viewer@test.invalid',now()),
 ('00000000-0000-0000-0000-000000000023','expense-outsider@test.invalid',now());
insert into ctx(bid,sid) select (public.flowledger_command('create_business','{"name":"Expense test","description":"","email":"","phone":"","address":"","currency":"LKR","timezone":"Asia/Colombo","opening_balance":"0","balance_date":"2026-01-01","business_days":[1,2,3,4,5]}') #>> '{}')::uuid,gen_random_uuid();
insert into results select is((select count(*)::integer from public.expenses where business_id=(select bid from ctx)),3,'monthly schedule creates three entries');
insert into results select is((select string_agg(due_date::text,',' order by due_date) from public.expenses where business_id=(select bid from ctx)),'2026-01-31,2026-02-28,2026-03-31','month ends clamp without drift');
insert into results select is((select sum(amount_minor)::bigint from public.expenses where business_id=(select bid from ctx)),30075::bigint,'amounts are exact');
insert into results select is((select count(*)::integer from public.expenses where business_id=(select bid from ctx)),3,'retry does not duplicate expenses');
insert into results select throws_ok($$select public.expense_command('category_delete',jsonb_build_object('business_id',bid,'id',cid,'version',1)) from ctx$$,'P0001','category is in use','referenced category protected');
insert into results select throws_ok($$select public.expense_command('delete',jsonb_build_object('business_id',bid,'id',eid,'version',9)) from ctx$$,'P0001','record changed; refresh and retry','stale edit rejected');
insert into results select is((select count(*)::integer from public.expenses where business_id=(select bid from ctx) and deleted_at is null),2,'delete affects one occurrence');
insert into results select is((select count(*)::integer from public.expenses where business_id=(select bid from ctx) and deleted_at is null),3,'restore returns expense');
insert into results select is((select count(*)::integer from public.expense_history where entity_id=(select eid from ctx)),3,'create delete restore recorded in history');
insert into results select throws_ok($$update public.expenses set title='forged'$$,'42501',null,'direct writes denied');
insert into public.business_members(business_id,user_id,role) select bid,'00000000-0000-0000-0000-000000000022','viewer' from ctx;
insert into results select is((select count(*)::integer from public.expenses where business_id=(select bid from ctx)),3,'viewer can read');
insert into results select throws_ok($$select public.expense_command('delete',jsonb_build_object('business_id',bid,'id',eid,'version',3)) from ctx$$,'P0001','permission denied','viewer cannot delete');
insert into results select is((select count(*)::integer from public.expense_history where business_id=(select bid from ctx)),0,'viewer cannot read owner history');
insert into results select is((select count(*)::integer from public.expenses where business_id=(select bid from ctx)),0,'outsider cannot read');
insert into results select throws_ok($$select public.expense_command('category_create',jsonb_build_object('business_id',bid,'name','Forged')) from ctx$$,'P0001','permission denied','outsider cannot mutate');
insert into results select is((select amount_minor from public.expenses where id=(select eid from ctx)),9010::bigint,'edit persists exact amount');
insert into results select is((select count(*)::integer from public.expenses where business_id=(select bid from ctx) and title='Rent'),2,'edit leaves other occurrences unchanged');
insert into results select throws_ok($$select public.expense_command('update',jsonb_build_object('business_id',bid,'id',eid,'version',4,'category_id','20000000-0000-0000-0000-000000000000','title','Invalid','amount','1','due_date','2026-02-01')) from ctx$$,'P0001','Choose an active category','category must belong to the business');
insert into results select throws_ok($$select public.expense_command('delete',jsonb_build_object('business_id',bid,'id',eid,'version',3)) from ctx$$,'P0001','permission denied','archived business cannot be changed');
insert into results select * from finish();
